using System.IO;using System.Text.Json;using System.Text.Json.Nodes;
namespace Spectra;
// Explicit, per-world P2P transfers. Account data, configs and saves are never enumerated.
public sealed class PartyPacks(Store store,GameService game):IDisposable
{
 public record FileEntry(string Kind,string Name,string Hash,long Size);
 public record Manifest(string Name,string Version,string Loader,string LoaderVersion,FileEntry[] Files);
 record Shared(string Path,long Size,long Ticks);
 sealed record Download(string Stage,Manifest Manifest,FileEntry[] Files);
 readonly Dictionary<string,Dictionary<string,Shared>> shares=new();readonly Dictionary<string,(Manifest Value,DateTime Time)> cached=new();readonly Dictionary<string,Download> downloads=new();readonly SemaphoreSlim gate=new(1,1);
 static readonly string[] Kinds=["mods","shaders","resources"];
 static string Folder(string kind)=>kind=="shaders"?"shaderpacks":kind=="resources"?"resourcepacks":"mods";
 static bool HashValid(string hash)=>hash!=null&&hash.Length==64&&hash.All(c=>c is >= 'a' and <= 'f' or >= '0' and <= '9');
 void Host(string world){if(!store.Config.ShareGameActivity||store.Config.HideOnlineStatus||!game.Running.ContainsKey(world)||!game.Activities.TryGetValue(world,out var activity)||activity.LanPort<1)throw new IOException("Мир не открыт для обмена");}
 public async Task<Manifest> Share(string world){await gate.WaitAsync();try{Host(world);var activity=game.Activities[world];var instance=new Instance{Id=world,Name=activity.Pack,Version=activity.Version,Loader=activity.Loader,LoaderVersion=activity.LoaderVersion};var root=store.Folder(instance);if(cached.TryGetValue(world,out var memo)&&DateTime.UtcNow-memo.Time<TimeSpan.FromSeconds(10)&&memo.Value.Version==activity.Version&&memo.Value.Loader==activity.Loader&&memo.Value.LoaderVersion==activity.LoaderVersion)return memo.Value;var files=new List<FileEntry>();var sources=new Dictionary<string,Shared>();long total=0;
 foreach(var kind in Kinds){var dir=Path.Combine(root,Folder(kind));if(!Directory.Exists(dir))continue;if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)throw new IOException("Нельзя передавать папку-ссылку");foreach(var file in Directory.EnumerateFiles(dir)){var info=new FileInfo(file);if(!Path.GetExtension(file).Equals(kind=="mods"?".jar":".zip",StringComparison.OrdinalIgnoreCase))continue;if((info.Attributes&FileAttributes.ReparsePoint)!=0||info.Length<1||info.Length>64L*1024*1024)throw new IOException("Недопустимый файл сборки");total+=info.Length;if(total>512L*1024*1024||files.Count>=2000)throw new IOException("Лимит сборки: 512 МиБ / 2000 файлов");var ticks=info.LastWriteTimeUtc.Ticks;var size=info.Length;var hash=await Net.Hash(file,"SHA256");info.Refresh();if(size!=info.Length||ticks!=info.LastWriteTimeUtc.Ticks)throw new IOException("Файл сборки изменился");files.Add(new(kind,info.Name,hash,size));sources[hash]=new(file,size,ticks);}}
 Host(world);shares[world]=sources;var manifest=new Manifest(activity.Pack,activity.Version,activity.Loader,activity.LoaderVersion,files.ToArray());cached[world]=(manifest,DateTime.UtcNow);return manifest;}finally{gate.Release();}}
 public async Task<string> Read(string world,string hash,long offset){await gate.WaitAsync();try{Host(world);if(!HashValid(hash)||!shares.TryGetValue(world,out var files)||!files.TryGetValue(hash,out var file)||offset<0||offset>=file.Size)throw new IOException("Неизвестный файл");var info=new FileInfo(file.Path);if((info.Attributes&FileAttributes.ReparsePoint)!=0||info.Length!=file.Size||info.LastWriteTimeUtc.Ticks!=file.Ticks)throw new IOException("Сборка изменилась");await using var input=new FileStream(file.Path,FileMode.Open,FileAccess.Read,FileShare.Read,65536,true);input.Position=offset;var bytes=new byte[(int)Math.Min(65536,file.Size-offset)];await input.ReadExactlyAsync(bytes);return Convert.ToBase64String(bytes);}finally{gate.Release();}}
 public static void Validate(Manifest manifest){if(manifest.Files==null||manifest.Files.Length>2000||manifest.Name==null||manifest.Name.Length>100||string.IsNullOrEmpty(manifest.Version)||manifest.Version.Length>40||!new[]{"vanilla","fabric","forge","quilt","neoforge"}.Contains(manifest.Loader)||manifest.LoaderVersion==null||manifest.LoaderVersion.Length>80)throw new IOException("Неверная сборка");long total=0;var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var sizes=new Dictionary<string,long>();foreach(var f in manifest.Files){if(f==null||!Kinds.Contains(f.Kind)||string.IsNullOrEmpty(f.Name)||f.Name.Length>180||f.Name!=Path.GetFileName(f.Name)||f.Name.IndexOfAny(Path.GetInvalidFileNameChars())>=0||f.Name.Any(c=>c<32||"/\\:*?\"<>|".Contains(c))||f.Name.EndsWith('.')||f.Name.EndsWith(' ')||System.Text.RegularExpressions.Regex.IsMatch(f.Name,@"^(con|prn|aux|nul|com[1-9]|lpt[1-9])(\.|$)",System.Text.RegularExpressions.RegexOptions.IgnoreCase)||!Path.GetExtension(f.Name).Equals(f.Kind=="mods"?".jar":".zip",StringComparison.OrdinalIgnoreCase)||!HashValid(f.Hash)||f.Size<1||f.Size>64L*1024*1024||!names.Add(f.Kind+"/"+f.Name))throw new IOException("Неверный файл сборки");if(sizes.TryGetValue(f.Hash,out var known)&&known!=f.Size)throw new IOException("Размеры одинаковых файлов не совпадают");sizes[f.Hash]=f.Size;total+=f.Size;}if(total>512L*1024*1024)throw new IOException("Сборка слишком большая");}
 public string Begin(Manifest manifest,string[] selected){Validate(manifest);if(downloads.Count>=2)throw new IOException("Уже загружаются две сборки");var wanted=selected.ToHashSet(StringComparer.Ordinal);var files=manifest.Files.Where(f=>wanted.Contains(f.Kind+"/"+f.Name)).ToArray();if(files.Length!=wanted.Count)throw new IOException("Выбраны неизвестные файлы");var id=Guid.NewGuid().ToString("N");var stage=Path.Combine(store.Root,"downloads","party-"+id);Directory.CreateDirectory(stage);downloads[id]=new(stage,manifest,files);return id;}
 public async Task Write(string id,string hash,long offset,string data){await gate.WaitAsync();try{if(!downloads.TryGetValue(id,out var session))throw new IOException("Загрузка закрыта");var file=session.Files.FirstOrDefault(f=>f.Hash==hash)??throw new IOException("Неизвестный файл");if(data.Length>90000||offset<0)throw new IOException("Неверный блок");var bytes=Convert.FromBase64String(data);if(bytes.Length<1||bytes.Length>65536||offset+bytes.Length>file.Size)throw new IOException("Неверный размер блока");var path=Path.Combine(session.Stage,hash);await using var output=new FileStream(path,FileMode.OpenOrCreate,FileAccess.Write,FileShare.None,65536,true);if(output.Length!=offset)throw new IOException("Неверный порядок блоков");output.Position=offset;await output.WriteAsync(bytes);}finally{gate.Release();}}
 public async Task<string> Commit(string id){await gate.WaitAsync();Instance? instance=null;try{if(!downloads.TryGetValue(id,out var session))throw new IOException("Загрузка закрыта");foreach(var file in session.Files.DistinctBy(f=>f.Hash)){var path=Path.Combine(session.Stage,file.Hash);if(!File.Exists(path)||new FileInfo(path).Length!=file.Size||await Net.Hash(path,"SHA256")!=file.Hash)throw new IOException("Контрольная сумма сборки не совпала");}instance=new Instance{CreatedAt=DateTime.UtcNow,Name=session.Manifest.Name,Version=session.Manifest.Version,Loader=session.Manifest.Loader,LoaderVersion=session.Manifest.LoaderVersion,Settings=store.Config.Defaults with{}};var root=store.Folder(instance);foreach(var file in session.Files){var dest=Store.SafePath(root,Folder(file.Kind)+"/"+file.Name);Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.Copy(Path.Combine(session.Stage,file.Hash),dest,false);}store.Config.Instances.Add(instance);store.Save();Cancel(id);return instance.Id;}catch{if(instance!=null){store.Config.Instances.Remove(instance);var root=Path.GetDirectoryName(store.Folder(instance))!;if(Directory.Exists(root))Directory.Delete(root,true);}throw;}finally{gate.Release();}}
 public void Cancel(string id){if(downloads.Remove(id,out var session)&&Directory.Exists(session.Stage))try{Directory.Delete(session.Stage,true);}catch(IOException){}}
 public void Reset(){cached.Clear();shares.Clear();foreach(var id in downloads.Keys.ToArray())Cancel(id);}
 public void Dispose()=>Reset();
}
